    "content": "女主 41 岁， 高中就开始慢慢有强迫症了。 说下症状 1 、每次洗手要 1 -2 个小时 。 2 、每次出去玩之后，回家里，会把身上穿的衣服都扔了，嫌脏， 行李要收拾 2-4 个小时。 3 、总感觉外面的东西不干净。 之前去宛平南路 600 号看过， 吃了点药会好些，现在停了， 好像变严重了。"
