    "content": "8月10日，住友商事宣布收购英国Gwynt Glas海上风电项目33.3%的股权，并作为战略合作伙伴加入该项目。该项目由EDF电力解决方案英国及爱尔兰公司（EDF power solutions UK and Ireland）和爱尔兰电力供应委员会（ESB）共同开发。Gwynt Glas项目位于英国凯尔特海，距离英国海岸约40公里，计划建设装机容量最高达1.5吉瓦的浮式海上风电场。项目预计于2028年提交许可申请，并计划于2030年代后期投入商业运营。（界面）"
