    "description": "近日，有网友发视频反映，在浙江宁波海曙区一公共充电站，一台极氪7X车辆突发起火。8月9日晚，极氪官方回应，该车辆近期曾发生严重碰撞事故，事后未通过官方授权服务中心检测及维修，具体原因以相关部门调查结论为准。",
