    "content": "快科技8月10日消息，不少日常通勤开车的人都有过类似的疑惑，好好的按喇叭这项基础驾驶操作，不知道从什么时候开始，居然在不少路人眼里成了带有挑衅意味的不当行为。 针对这种普遍存在的认知错位现象，近期有媒体和行业专家公开发声，鸣笛从被设计出来的核心作用，就只是用来提醒前车或者周边行人留意路况风险，从来都不是供司机发泄个人情绪的出气筒。 现在路面上的鸣笛乱象早就脱离了原本的功能初衷，有些司机按喇叭手直接粘在按键上不肯抬起来，一声长鸣能连续响十多秒，刺耳的声响隔着半条街都能清晰传到路人耳朵里。还有人按喇叭跟打地鼠似的，嘀嘀…"
