    "content": "新华社北京8月10日电 英国媒体《卫报》9日报道，关于英国6月发生的两起骚乱事件，美国企业家马斯克旗下社交媒体平台X上流量最高的帖文有相当数量源自美国账号，该平台已成为外国极右翼势力制造舆论对立的武器。 6月8日，英国北爱尔兰首府贝尔法斯特发生一起恶性持刀袭击事件，嫌疑人为一名苏丹裔男子。案发后，记录袭击过程的视频在社交媒体上广泛传播，极右翼人士煽风点火，引发巨大震动。贝尔法斯特随后发生“打砸抢”，至少12名警员受伤。同月，在英格兰南部城市南安普敦，也发生一起嫌疑人为印度裔的凶杀案，当地反移民情绪被点燃，爆发大规模…"
