    "author": "",
    "description": "“大数据是机器学习的驱动力”。“AI教母”李飞飞的这一结论，正被越来越多AI从业者接受和认同。其中也包括前华为“天才少年”、墨奇智能CTO黄青虬。 在墨奇智能完成了十几亿元的天使轮系列融资后，36氪在上海见到了黄青虬。他对36氪表示：“假设数据质量无限高，再简单的模型也能训出很好的结果。” 在一众具身智能创企讲述的眩目故事中，黄青虬这套围绕数据的解题思路，显得很朴素，也很务实。 黄青虬是华为第二届“天才少年”，2020年他以这一身份加入…",
    "content": "“大数据是机器学习的驱动力”。“AI教母”李飞飞的这一结论，正被越来越多AI从业者接受和认同。其中也包括前华为“天才少年”、墨奇智能CTO黄青虬。 在墨奇智能完成了十几亿元的天使轮系列融资后，36氪在上海见到了黄青虬。他对36氪表示：“假设数据质量无限高，再简单的模型也能训出很好的结果。” 在一众具身智能创企讲述的眩目故事中，黄青虬这套围绕数据的解题思路，显得很朴素，也很务实。 黄青虬是华为第二届“天才少年”，2020年他以这一身份加入华为车BU，担任自动驾驶AI部门负责人。在华为期间，黄青虬先后主导攻克了激光感知…"
