    "author": "夏晓,温新年",
    "description": "新华社迪拜8月10日电 通讯｜中国自动驾驶出租车“驶入”阿联酋 新华社记者夏晓 温新年 8月的阿联酋迪拜，中午室外气温接近50摄氏度。记者在迪拜的朱迈拉海滨打开“萝卜快跑”手机应用，不到两分钟，一辆黑色汽车缓缓停靠路边。没有驾驶员，也没有方向盘。手机解锁车门，凉意扑面而来，车内宽敞整洁，语音提示“请系好安全带”后，车辆平稳起步。 汽车沿着海滨路驰骋，车窗外，碧蓝的海湾与形如风帆的迪拜卓美亚帆船酒店相映成景。无论遇到环岛、信号灯还是车流，…",
    "content": "新华社迪拜8月10日电 通讯｜中国自动驾驶出租车“驶入”阿联酋 新华社记者夏晓 温新年 8月的阿联酋迪拜，中午室外气温接近50摄氏度。记者在迪拜的朱迈拉海滨打开“萝卜快跑”手机应用，不到两分钟，一辆黑色汽车缓缓停靠路边。没有驾驶员，也没有方向盘。手机解锁车门，凉意扑面而来，车内宽敞整洁，语音提示“请系好安全带”后，车辆平稳起步。 汽车沿着海滨路驰骋，车窗外，碧蓝的海湾与形如风帆的迪拜卓美亚帆船酒店相映成景。无论遇到环岛、信号灯还是车流，自动驾驶出租车都能精准地完成每一次转向和变道。若非驾驶位空无一人，很难让人意识到…"
