    "title": "券商加强新开户审核、加大两融审查力度？多家回应：合规要求一贯严格 不存在“从严”",
    "link": "https://36kr.com/newsflashes/3933258270424452?f=rss",
    "pub_date": "2026-08-10 13:17:13",
    "author": "",
    "description": "今日有报道消息称，包括中信证券、东方财富在内的多家券商近期收紧新开户审核及两融、期权交易审查。从中信证券、东方财富方面了解到，两公司融资融券及衍生品业务合规要求一直是严格且规范的，不存在所谓“从严”，两公司强调相关业务始终在监管框架下平稳运行。此外，就上述报道中提到的“7月下旬越来越多散户被迫平仓离场”的说法，记者从行业了解到，多家券商信用业务已在各个业务环节逐一化解风险，客户自身也主动补充保证金，市场整体风险可控。（财联社）",
