    "content": "这周末，年度大片《》在中国内地正式上映了。 它是第一部从头到尾都用 IMAX 摄影机拍摄的电影，剧组跑了六个国家，拍掉 210 万英尺（约 640 公里）的 IMAX 胶片，光把这些胶片首尾相连，都够从北京铺到郑州了。 这么一部冲着电影院硬件上限拍出来的电影，观众如果最后随便找个厅看，好像多少有点辜负导演。 但是，多少人跟我一样，打开购票软件时，两眼一黑...... 看起来都很厉害的样子｜淘票票 IMAX、激光 IMAX、杜比影院、杜比全景声厅、CINITY、中国巨幕、4DX……真是眼花缭乱。每一个都好像比普通厅高…"
