    "description": "新华社纽约8月9日电（记者尚绪谦）北美防空司令部9日在社交媒体发文说，当天出动F-16战斗机，拦截多架进入位于美国新泽西州贝德敏斯特镇的特朗普国家高尔夫球俱乐部附近临时禁飞区域的民用飞机。 帖文说，所有闯入临时禁飞区的民用飞机均被安全带离。 据美国媒体报道，北美防空司令部共拦截两架民用飞机。另有第三架飞机的飞行动向触发警报，导致当天在俱乐部出席活动的美国总统特朗普推迟离开。这架飞机在重新联络上后恢复合规飞行，北美防空司令部未派战机进行拦…",
    "content": "新华社纽约8月9日电（记者尚绪谦）北美防空司令部9日在社交媒体发文说，当天出动F-16战斗机，拦截多架进入位于美国新泽西州贝德敏斯特镇的特朗普国家高尔夫球俱乐部附近临时禁飞区域的民用飞机。 帖文说，所有闯入临时禁飞区的民用飞机均被安全带离。 据美国媒体报道，北美防空司令部共拦截两架民用飞机。另有第三架飞机的飞行动向触发警报，导致当天在俱乐部出席活动的美国总统特朗普推迟离开。这架飞机在重新联络上后恢复合规飞行，北美防空司令部未派战机进行拦截。"
