    "content": "8月10日，上海市公安局浦东分局发布通报称，一男子发布涉台风不实信息被处以行政拘留。无独有偶，同一天，公安部网安局公布了编造传播涉汛等涉灾网络谣言违法犯罪活动的15起典型案例。官方部门的密集通报，展现了打击涉汛谣言、维护防汛救灾秩序的坚定决心。 每当台风、汛情来临，总有一些人将灾难视为流量密码，炮制、传播各类虚假的涉灾信息。从通报来看，涉汛等涉灾谣言的类型，可谓五花八门。比如有的无中生有，将与台风毫无关联的视频剪辑拼接，谎称“台风天有人被困塔吊”；有的移花接木，把往年水灾画面，或外地灾情视频包装成“刚刚发生”。更有…"
