    "content": "AI产品经理的起点不是模型，而是定义问题。本文从外卖需求案例出发，拆解从用户问题到产品方案再到模型能力的完整链路，帮你避开“看到需求就画功能，看到AI就做Agent”的常见误区。 首先，在讲知识之前，先让我们看一个外卖的需求案例。 一位上班族每天点外卖。中午11点50分，他还在处理工作，一小时后又要开会。他希望平台增加一个按钮，直接购买上次的外卖。 如果把用户的话直接当成需求，答案似乎很简单：做一个按钮。 但继续追问就会发现，他真正想解决的并不是“平台少了一个按钮”，而是在时间紧张、注意力被工作占用时，不想再花精力…"
